def transform(repo: Repository, record: dict) -> dict:
    """Normalize a raw task record's identifier and whitespace in the title."""
    normalized = {"id": str(record["id"]), "title": record["title"].strip()}
    return write_to_db(repo, normalized)

def write_to_db(repo: Repository, record: dict) -> dict:
    """Persist a normalized incoming record through the repository."""
    return repo.save(record)

def run_pipeline(repo: Repository, records: list[dict]) -> list[dict]:
    """Normalize and write each incoming task record."""
    return [transform(repo, record) for record in records]

def format_notification(task: dict) -> str:
    """Format a task-created notification using its title."""
    return "Task created: " + task["title"]

def send_email(message: str) -> str:
    """Represent delivery to the email sink."""
    return message

def notify(task: dict) -> str:
    """Format a task notification and send it by email."""
    return send_email(format_notification(task))

@with_retries(attempts=3)
def create_task(repo: Repository, title: str) -> dict:
    """Create and persist a task, then notify subscribers; retry transient errors."""
    task = repo.save({"id": title.lower().replace(" ", "-"), "title": title})
    notify(task)
    return task

def complete_task(repo: Repository, task_id: str) -> dict:
    """Mark an existing task complete; missing tasks raise KeyError."""
    task = repo.get(task_id)
    if task is None:
        raise KeyError(task_id)
    task["done"] = True
    return repo.save(task)

def process(repo: Repository, titles: list[str]) -> list[dict]:
    """Process titles into stored task records."""
    return [create_task(repo, title) for title in titles]

def walk_tree(node: dict) -> list[str]:
    """Recursively collect names in a task hierarchy in preorder."""
    names = [node["name"]]
    for child in node.get("children", []):
        names.extend(walk_tree(child))
    return names

def is_even(value: int) -> bool:
    """Determine parity through mutual recursion with is_odd."""
    return True if value == 0 else is_odd(value - 1)

def is_odd(value: int) -> bool:
    """Determine parity through mutual recursion with is_even."""
    return False if value == 0 else is_even(value - 1)

def parse_config(text: str) -> dict:
    """Parse a JSON configuration object and require an authentication secret."""
    config = json.loads(text)
    if not isinstance(config, dict) or not config.get("secret"):
        raise ValueError("Configuration requires a secret")
    return config

def load_config(path: str) -> dict:
    """Read configuration from a file and validate it."""
